script:
(function () {
  'use strict';
  // 2026 federal marginal and effective income tax rates on ordinary income.
  //   AGI = gross income - pre-tax contributions and adjustments
  //   taxable income = AGI - (standard deduction incl. 65+/blind additions, or itemized amount)
  //                    - senior deduction ($6,000 per person 65+, less 6% of AGI over $75,000 /
  //                      $150,000 joint; not for married filing separately)
  //   tax = sum over the seven brackets; marginal rate = rate of the bracket holding the last
  //   dollar of taxable income; room left = top of that bracket - taxable income.
  //   Effective rate = tax / gross income. "Next dollars" rate = (tax(income + extra) - tax(income)) / extra,
  //   which also picks up bracket crossings and the senior deduction phase-out.
  // Verified (Node, scratch tests, against hand calculations from the Rev. Proc. 2025-32 tables):
  //   Single $75,000 -> taxable $58,900, tax $7,670.00 (= $5,800 + 22% x $8,500; same as
  //     take-home-paycheck-calculator), marginal 22%, room $46,800 to the 24% bracket.
  //   MFJ $100,000 -> taxable $67,800, tax $7,640.00, marginal 12%, room $33,000.
  //   Rev. Proc. base amounts reproduce: single tax at $105,700 = $17,966; MFJ at $768,700 = $206,583.50;
  //     HOH at $640,600 = $191,171.
  //   Single 65+, $80,000 -> deduction $16,100 + $2,050 + ($6,000 - 6% x $5,000 = $5,700) = $23,850,
  //     taxable $56,150, tax $7,065.00; next $1,000 costs 22% x 1.06 = 23.32%.
  //   Income below the deduction -> tax $0, marginal 0%.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------------
  // Brackets, standard deductions and the additional 65+/blind amounts: IRS Rev. Proc. 2025-32,
  //   sections 4.01 and 4.14 (as amended by P.L. 119-21). Senior deduction ($6,000, 6% phase-out over
  //   $75,000 / $150,000 joint, tax years 2025-2028, not for married filing separately): IRC 151(d)(5)(C),
  //   Schedule 1-A (Form 1040). Same constants as take-home-paycheck-calculator and income-tax-calculator.
  var TAX_YEAR = 2026;
  var KEY = { single: 'single', mfj: 'mfj', mfs: 'mfs', hoh: 'hoh', qss: 'mfj' }; // QSS uses joint brackets
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150, qss: 32200 };
  var ADDITIONAL_STD = { single: 2050, hoh: 2050, mfj: 1650, mfs: 1650, qss: 1650 }; // per 65+ or blind
  var SENIOR_DEDUCTION = 6000, SENIOR_RATE = 0.06;
  var SENIOR_PHASE = { single: 75000, hoh: 75000, qss: 75000, mfj: 150000 };
  // -----------------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function pct(x, d) { return (x * 100).toFixed(d === undefined ? 1 : d).replace(/\.0+$/, '') + '%'; }

  function el(id) { return document.getElementById(id); }
  function raw(id) { return el(id).value.trim() === '' ? 0 : parseFloat(el(id).value); }

  function bracketTax(taxable, key) {
    var limits = BRACKETS[key], tax = 0, lower = 0, bands = [];
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      var amt = Math.max(0, Math.min(taxable, upper) - lower);
      bands.push({ rate: RATES[i], lower: lower, upper: upper, amount: amt, tax: amt * RATES[i] });
      tax += amt * RATES[i];
      lower = upper;
    }
    return { tax: tax, bands: bands };
  }

  function compute(o) {
    var s = o.status, key = KEY[s], spouseCounts = s === 'mfj' || s === 'mfs';
    var agi = o.income - o.adjust;
    var extras = (o.you65 ? 1 : 0) + (o.youBlind ? 1 : 0) + (spouseCounts ? (o.spouse65 ? 1 : 0) + (o.spouseBlind ? 1 : 0) : 0);
    var standard = STANDARD_DEDUCTION[s] + extras * ADDITIONAL_STD[s];
    var base = o.itemize ? o.itemized : standard;
    var seniors = (o.you65 ? 1 : 0) + (s === 'mfj' && o.spouse65 ? 1 : 0), senior = 0;
    if (s !== 'mfs' && seniors > 0)
      senior = seniors * Math.max(0, SENIOR_DEDUCTION - SENIOR_RATE * Math.max(0, agi - SENIOR_PHASE[s]));
    var deduction = base + senior;
    var taxable = Math.max(0, agi - deduction);
    var bt = bracketTax(taxable, key);
    var idx = -1;
    if (taxable > 0) for (idx = 0; idx < bt.bands.length - 1 && taxable > bt.bands[idx].upper; idx++);
    return { agi: agi, deduction: deduction, senior: senior, taxable: taxable, tax: bt.tax, bands: bt.bands, idx: idx };
  }

  function cell(text) { var td = document.createElement('td'); td.textContent = text; return td; }

  function update() {
    var s = el('mtStatus').value, itemize = el('mtDeduction').value === 'itemized';
    var o = {
      status: s, income: raw('mtIncome'), adjust: raw('mtAdjust'), itemize: itemize, itemized: raw('mtItemized'),
      you65: el('mtYou65').checked, youBlind: el('mtYouBlind').checked,
      spouse65: el('mtSpouse65').checked, spouseBlind: el('mtSpouseBlind').checked, extra: raw('mtExtra')
    };
    el('mtItemizedWrap').hidden = !itemize;
    el('mtSpouseWrap').hidden = !(s === 'mfj' || s === 'mfs');
    var error = el('mtError');
    var bad = [o.income, o.adjust, o.itemized, o.extra].some(function (v) { return isNaN(v) || !isFinite(v) || v < 0 || v > 1e10; });
    error.hidden = !bad;
    if (bad) { error.textContent = 'Enter amounts of $0 or more.'; return; }

    var r = compute(o);
    var rate = r.idx < 0 ? 0 : RATES[r.idx];
    el('mtMarginal').textContent = pct(rate, 0);
    el('mtEffective').textContent = o.income > 0 ? pct(r.tax / o.income, 2) : '0%';
    el('mtTax').textContent = money.format(r.tax);
    el('mtTaxable').textContent = money.format(r.taxable);
    el('mtDeductionUsed').textContent = money.format(r.deduction) + (r.senior > 0 ? ' (incl. ' + whole.format(r.senior) + ' senior deduction)' : '');
    el('mtAverage').textContent = r.taxable > 0 ? pct(r.tax / r.taxable, 2) : '0%';
    var room;
    if (r.idx < 0) room = whole.format(Math.max(0, r.deduction - r.agi)) + ' more before any tax (then 10%)';
    else if (r.idx >= RATES.length - 1) room = 'None: this is the top bracket';
    else room = money.format(r.bands[r.idx].upper - r.taxable) + ' more before ' + pct(RATES[r.idx + 1], 0);
    el('mtRoom').textContent = room;

    var extraRow = el('mtExtraRate');
    if (o.extra > 0) {
      var r2 = compute({ status: o.status, income: o.income + o.extra, adjust: o.adjust, itemize: o.itemize, itemized: o.itemized,
                         you65: o.you65, youBlind: o.youBlind, spouse65: o.spouse65, spouseBlind: o.spouseBlind });
      var add = r2.tax - r.tax;
      extraRow.textContent = money.format(add) + ' (' + pct(add / o.extra, 2) + ' of the extra ' + whole.format(o.extra) + ')';
    } else extraRow.textContent = '–';

    var body = el('mtBrackets');
    while (body.firstChild) body.removeChild(body.firstChild);
    r.bands.forEach(function (b, i) {
      var tr = document.createElement('tr');
      tr.appendChild(cell(pct(b.rate, 0)));
      tr.appendChild(cell(b.upper === Infinity ? 'Over ' + whole.format(b.lower) : whole.format(i === 0 ? 0 : b.lower + 1) + ' to ' + whole.format(b.upper)));
      tr.appendChild(cell(money.format(b.amount)));
      tr.appendChild(cell(money.format(b.tax)));
      if (i === r.idx) tr.className = 'font-semibold';
      body.appendChild(tr);
    });
    var tot = document.createElement('tr');
    tot.className = 'font-semibold';
    tot.appendChild(cell('Total'));
    tot.appendChild(cell(TAX_YEAR + ' taxable income'));
    tot.appendChild(cell(money.format(r.taxable)));
    tot.appendChild(cell(money.format(r.tax)));
    body.appendChild(tot);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mtForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
